SELECT t1.slice_annotation_id, t1.annotation_id, t1.special_image_id, t1.special_id, t1.image_id, t1.area, t1.measure, t1.perimeter, t1.category_id, t1.description, t1.annotation_type, t1.measure_full_name, t1.measure_type, t1.measure_relation, t1.measure_name, t1.measure_number, t1.radius, t1.mean_distance, t1.max_distance, min_distance, inner_angle, exterior_angle, center_point, point_count, t1.location_type, create_by, create_time, update_by, update_time, ST_ASTEXT ( t1.location ) AS location, t1.geometry, t1.update_by, t1.update_time FROM tb_special_annotation t1
AND t1.special_id = #{specialId}
AND t1.special_image_id = #{specialImageId}
AND t1.slice_annotation_id = #{sliceAnnotationId}
ORDER BY t1.create_time desc

